    words = ' '.join(paragraphs).split(' ')
    lines, line = [], ''
    for word in words:
        if len(line) + len(word) + 1 <= width:
            line += ' ' + word
        else:
            lines.append(line.strip())
            line = word
    lines.append(line.strip())
    return '\n'.join(lines)
```

